#!/usr/bin/env Rscript

suppressPackageStartupMessages({ library(optparse); library(jsonlite); library(ggplot2) })
`%||%` <- function(x, y) if (is.null(x) || !length(x)) y else x
op <- parse_args(OptionParser(option_list=list(make_option('--input',type='character'),make_option('--params',type='character'),make_option('--output',type='character'))))
out <- op$output %||% getwd(); dir.create(out,recursive=TRUE,showWarnings=FALSE)
unlink(file.path(out,c('result.svg','result.pdf','result.png','result.html','figure.json','motif_data_used.csv','selected_rows.csv','error.json','run.log')),force=TRUE)
logmsg <- function(x) { line <- sprintf('[%s] %s\n',format(Sys.time(),'%F %T'),x); cat(line); cat(line,file=file.path(out,'run.log'),append=TRUE) }
fail <- function(message,detail='',suggestion='Check input columns and params.json.') { writeLines(toJSON(list(error=message,detail=detail,suggestion=suggestion),auto_unbox=TRUE,pretty=TRUE),file.path(out,'error.json')); quit(status=1) }
readtab <- function(x) if(tolower(tools::file_ext(x)) %in% c('tsv','txt')) read.delim(x,check.names=FALSE,stringsAsFactors=FALSE) else read.csv(x,check.names=FALSE,stringsAsFactors=FALSE)
main <- function() {
  if(is.null(op$input)||!file.exists(op$input)) fail('Input file not found',as.character(op$input))
  p <- if(!is.null(op$params)&&file.exists(op$params)) fromJSON(op$params,simplifyVector=FALSE) else list()
  val <- function(n,d=NULL,aliases=character()) { x<-p[[n]]; if(is.null(x)) for(g in names(p)) if(is.list(p[[g]])&&!is.null(p[[g]][[n]])){x<-p[[g]][[n]];break}; if(is.null(x)) for(a in aliases) if(!is.null(p[[a]])){x<-p[[a]];break}; x%||%d }
  vec <- function(x) { if(is.null(x)) return(character()); x<-unlist(x,use.names=FALSE); if(length(x)==1&&grepl(',',x,fixed=TRUE))x<-strsplit(x,',',fixed=TRUE)[[1]]; trimws(as.character(x)) }
  num <- function(n,d=0) { x<-suppressWarnings(as.numeric(unlist(val(n,d))[1])); ifelse(is.finite(x),x,d) }
  boo <- function(n,d=FALSE) { x<-val(n,d); if(is.logical(x))isTRUE(x[1]) else tolower(as.character(x[1]))%in%c('true','t','yes','y','1','on') }
  d0<-readtab(op$input); cn<-names(d0); low<-tolower(cn); findcol<-function(x,defaults=character()){h<-match(tolower(c(x,defaults)),low);h<-h[!is.na(h)];if(length(h))cn[h[1]] else NULL}
  mode<-tolower(as.character(val('input_mode','auto'))); if(!mode%in%c('auto','long','wide'))fail('Unsupported input_mode',mode)
  motifc<-findcol(val('motif_column',NULL),c('motif','motif_name','motif_id','name')); posc<-findcol(val('position_column',NULL),c('position','pos','index'))
  base_map<-val('base_columns',NULL); getbase<-function(b){x<-NULL;if(is.list(base_map)||!is.null(names(base_map)))x<-base_map[[b]];found<-findcol(x,b);if(is.null(found))'' else found}
  bcols<-setNames(vapply(c('A','C','G','T'),getbase,character(1)),c('A','C','G','T')); long_ok<-!is.null(motifc)&&!is.null(posc)&&all(nzchar(bcols)); is_long<-mode=='long'||(mode=='auto'&&long_ok)
  if(is_long&&!long_ok)fail('Long input requires motif, position, A, C, G, and T columns')
  keep<-rep(TRUE,nrow(d0)); inc<-vec(val('motifs_include')); exc<-vec(val('motifs_exclude'))
  if(!is.null(motifc)){ if(length(inc))keep<-as.character(d0[[motifc]])%in%inc; if(length(exc))keep<-keep&!(as.character(d0[[motifc]])%in%exc) }
  d<-d0[keep,,drop=FALSE]; write.csv(d,file.path(out,'selected_rows.csv'),row.names=FALSE)
  rows<-list(); k<-0
  if(is_long) for(i in seq_len(nrow(d))) { for(b in c('A','C','G','T')) {k<-k+1;rows[[k]]<-data.frame(motif=as.character(d[[motifc]][i]),position=as.character(d[[posc]][i]),base=b,raw_weight=suppressWarnings(as.numeric(d[[bcols[[b]]]][i])),stringsAsFactors=FALSE)} }
  else {
    if(is.null(motifc)) motifc<-cn[1]
    pat<-regexec('^(?:position[_-]?)?([ACGT])[_-]?([0-9]+)$',toupper(setdiff(cn,motifc))); mm<-regmatches(setdiff(cn,motifc),pat); valid<-which(lengths(mm)==3)
    if(!length(valid))fail('Wide input has no grouped A/C/G/T columns','Expected A1,C1,G1,T1 or A_1,C_1,G_1,T_1')
    groups<-sort(unique(vapply(mm[valid],function(x)x[3],character(1)))); for(i in seq_len(nrow(d))) for(pos in groups) for(b in c('A','C','G','T')) {hit<-which(toupper(cn)==paste0(b,pos)|toupper(cn)==paste0(b,'_',pos)|toupper(cn)==paste0('POSITION_',b,pos)|toupper(cn)==paste0('POSITION_',b,'_',pos));if(length(hit)){k<-k+1;rows[[k]]<-data.frame(motif=as.character(d[[motifc]][i]),position=pos,base=b,raw_weight=suppressWarnings(as.numeric(d[[cn[hit[1]]]][i])),stringsAsFactors=FALSE)}}
  }
  z<-do.call(rbind,rows);z<-z[is.finite(z$raw_weight)&!is.na(z$motif)&nzchar(z$motif),,drop=FALSE];if(!nrow(z))fail('No valid motif weights remain')
  motifs<-unique(z$motif); requested<-vec(val('motif_order'));if(length(requested))motifs<-unique(c(requested,motifs));motifs<-motifs[motifs%in%unique(z$motif)];if(boo('reverse_positions',FALSE))z$position<-factor(z$position,levels=rev(unique(z$position)))
  positions<-unique(as.character(z$position)); if(!boo('reverse_positions',FALSE))positions<-positions[order(suppressWarnings(as.numeric(positions)),positions)] else positions<-rev(positions); z$motif<-factor(z$motif,levels=motifs);z$position<-factor(as.character(z$position),levels=positions)
  scale_in<-tolower(as.character(val('input_scale','weight'))); norm<-tolower(as.character(val('normalize','probability'))); z$raw_nonnegative<-pmax(0,z$raw_weight)
  z$probability<-ave(z$raw_nonnegative,interaction(z$motif,z$position,drop=TRUE),FUN=function(x){if(norm=='probability')if(sum(x)>0)x/sum(x)else rep(.25,length(x)) else x})
  z$probability<-pmin(1,pmax(0,z$probability)); bg<-unlist(val('background_frequencies',list(A=.25,C=.25,G=.25,T=.25)));bg<-as.numeric(bg[c('A','C','G','T')]);if(any(!is.finite(bg))||sum(bg)<=0)bg<-rep(.25,4);bg<-bg/sum(bg); names(bg)<-c('A','C','G','T')
  info<-tapply(seq_len(nrow(z)),interaction(z$motif,z$position,drop=TRUE),function(ix){pp<-z$probability[ix];bb<-bg[z$base[ix]];if(boo('information_content',TRUE))max(0,min(2,sum(ifelse(pp>0,pp*log2(pp/bb),0)))) else 1});z$information<-as.numeric(info[interaction(z$motif,z$position,drop=TRUE)]);z$height<-if(boo('information_content',TRUE))z$probability*z$information else z$probability
  z<-z[z$height>=num('min_letter_height',0),,drop=FALSE];if(!nrow(z))fail('No letters remain after min_letter_height filtering');z$y_min<-NA_real_;z$y_max<-NA_real_;z$y_mid<-NA_real_;nmot<-length(motifs)
  for(m in motifs) for(po in positions){ix<-which(z$motif==m&z$position==po);if(length(ix)){ord<-ix[order(z$height[ix],z$base[ix])];cum<-c(0,cumsum(z$height[ord]));row<-nmot-match(m,motifs)+1;z$y_min[ord]<-row-cum[-length(cum)];z$y_max[ord]<-row-cum[-1];z$y_mid[ord]<-(z$y_min[ord]+z$y_max[ord])/2}}
  z<-z[is.finite(z$y_mid),,drop=FALSE];write.csv(z[,c('motif','position','base','raw_weight','probability','information','height','y_min','y_max')],file.path(out,'motif_data_used.csv'),row.names=FALSE)
  colors<-c(A='#19b51b',C='#1737cf',G='#f5a300',T='#d60000');lc<-unlist(val('letter_colors',NULL),use.names=TRUE);if(length(lc)){if(is.null(names(lc)))colors<-setNames(rep(lc,length.out=4),names(colors))else colors[names(lc)]<-lc}
  z$tip<-sprintf('motif: %s<br>position: %s<br>base: %s<br>raw weight: %s<br>probability: %.5f<br>height: %.5f',z$motif,z$position,z$base,format(signif(z$raw_weight,6),trim=TRUE),z$probability,z$height)
  w<-num('width',max(8,1+length(positions)*num('width_per_position',.55)));h<-num('height',max(3,nmot*num('height_per_motif',1.05))); ybreak<-seq_len(nmot); ylab<-if(boo('show_motif_labels',TRUE))motifs else rep('',nmot); title<-val('title','Motif enrichment'); q<-ggplot(z,aes(x=as.numeric(position),y=y_mid,label=base,colour=base,text=tip))+geom_text(aes(size=pmax(2.2,pmin(15,height*10))),family=if(tolower(val('letter_font','sans'))=='arial')'Arial' else 'sans',alpha=num('letter_alpha',1),show.legend=FALSE)+scale_colour_manual(values=colors,guide='none')+scale_size_identity()+scale_x_continuous(breaks=seq_along(positions),labels=if(length(vec(val('position_labels')))==length(positions))vec(val('position_labels')) else positions,expand=c(.02,.02))+scale_y_continuous(breaks=ybreak,labels=ylab,limits=c(.25,nmot+.75),expand=c(0,0))+labs(title=if(boo('title_show',TRUE))title else NULL,x=val('xlab','Position'),y=val('ylab','Motif'))+theme_minimal(base_size=num('base_size',11),base_family=val('font_family','sans'))+theme(panel.background=element_rect(fill=val('panel_background','#FFFFFF'),colour=NA),plot.background=element_rect(fill=val('plot_background','#FFFFFF'),colour=NA),panel.grid=if(boo('grid_show',FALSE))element_line(colour=val('grid_color','#E6E6E6'))else element_blank(),axis.text.y=element_text(size=num('motif_label_size',11),colour=val('motif_label_color','#222222'),hjust=num('motif_label_hjust',1)),axis.text.x=element_text(angle=num('position_text_angle',0),hjust=if(num('position_text_angle',0)>0)1 else .5),plot.title=element_text(size=num('title_size',16),colour=val('title_color','#222222'),face=val('title_face','bold'),hjust=.5),legend.position=if(boo('legend_show',FALSE))val('legend_position','right')else'none')
  dpi<-as.integer(num('dpi',300));ggsave(file.path(out,'result.svg'),q,width=w,height=h,units='in');ggsave(file.path(out,'result.pdf'),q,width=w,height=h,units='in');ggsave(file.path(out,'result.png'),q,width=w,height=h,units='in',dpi=dpi)
  if(boo('interactive',TRUE)){if(!requireNamespace('plotly',quietly=TRUE)||!requireNamespace('htmlwidgets',quietly=TRUE))fail('plotly / htmlwidgets not available');pl<-plotly::ggplotly(q,tooltip='text');pl<-plotly::config(pl,displaylogo=FALSE,scrollZoom=boo('zoom',TRUE),modeBarButtonsToAdd=if(boo('lasso_select',FALSE)||boo('selectable',FALSE))c('lasso2d','select2d')else character());htmlwidgets::saveWidget(pl,file.path(out,'result.html'),selfcontained=TRUE)}else writeLines('<html><body><p>Interactive Plotly output is disabled.</p></body></html>',file.path(out,'result.html'))
  per<-lapply(motifs,function(m){x<-z[z$motif==m,];list(n_letters=nrow(x),n_positions=length(unique(x$position)),total_height=round(sum(x$height),6),max_height=round(if(nrow(x))max(x$height)else 0,6))});names(per)<-motifs;fig<-list(plugin='interactive_motif_logo_plot',title=title,motifs=as.character(motifs),n_motifs=nmot,n_positions=length(positions),bases=c('A','C','G','T'),information_content=boo('information_content',TRUE),input_scale=scale_in,n_letters=nrow(z),ranges=list(position=c(1,length(positions)),height=range(z$height)),per_motif_summary=per,outputs=c('result.svg','result.pdf','result.png','result.html','figure.json','run.log','motif_data_used.csv','selected_rows.csv'));writeLines(toJSON(fig,auto_unbox=TRUE,pretty=TRUE),file.path(out,'figure.json'));unlink(file.path(out,'error.json'),force=TRUE);logmsg(sprintf('Finished interactive_motif_logo_plot: %d motifs, %d positions, %d letters',nmot,length(positions),nrow(z)))
}
tryCatch(main(),error=function(e)fail('Plot generation failed',conditionMessage(e)))
